#!/usr/bin/env bash
# =====================================================================
#  AI 사무실 — 서버 설치 (Ubuntu 22.04 / 24.04, Oracle Cloud 무료 서버용)
#  하는 일: Node.js · AI 사무실 · 무료 AI(Ollama) · https(Caddy) · 방화벽 · 자동 실행
#  다시 실행하면 프로그램만 새 버전으로 바꾸고, 자료·설정·비밀번호는 그대로 둬요.
#
#  쓰는 법 (서버에서):  sudo AIO_PASSWORD='내 비밀번호' bash install.sh
#  고를 수 있는 것:
#    AIO_PASSWORD   처음 로그인 비밀번호 (8글자 이상). 없으면 만들어서 알려 줘요.
#    AIO_DOMAIN     내 도메인이 있으면 (예: office.example.com). 없으면 <IP>.sslip.io 를 써요.
#    AIO_MODEL      처음 받아 둘 무료 AI (기본 qwen2.5-coder:3b, 안 받으려면 none)
#    AIO_NO_OLLAMA=1  무료 AI를 설치하지 않기 (AI 키만 쓸 때)
# =====================================================================
set -euo pipefail

main() {
AIO_DIR=/opt/ai-office
AIO_USER=aioffice
AIO_VERSION="20261004-0855"
LOG=/var/log/ai-office-install.log
exec > >(tee -a "$LOG") 2>&1
step() { echo; echo "==> $*"; }
fail() { echo; echo "!! 설치하지 못했어요: $*"; echo "   자세한 기록: $LOG"; exit 1; }

[ "$(id -u)" = 0 ] || fail "관리자 권한이 필요해요. 앞에 sudo 를 붙여 주세요."
. /etc/os-release
[ "${ID:-}" = ubuntu ] || fail "Ubuntu 서버에서만 설치할 수 있어요 (지금: ${PRETTY_NAME:-알 수 없음})."
export DEBIAN_FRONTEND=noninteractive
case "$(dpkg --print-architecture)" in
  arm64) NARCH=linux-arm64 ;;
  amd64) NARCH=linux-x64 ;;
  *) fail "이 서버 종류($(dpkg --print-architecture))는 아직 지원하지 않아요." ;;
esac
echo "AI 사무실 서버 설치 시작 (버전 $AIO_VERSION, $(date))"

# ---------------------------------------------------------------
step "1/8 기본 프로그램 설치"
echo iptables-persistent iptables-persistent/autosave_v4 boolean true | debconf-set-selections
echo iptables-persistent iptables-persistent/autosave_v6 boolean true | debconf-set-selections
apt-get update -y
apt-get install -y curl ca-certificates xz-utils python3 python3-pil gnupg debian-keyring debian-archive-keyring apt-transport-https iptables-persistent

# ---------------------------------------------------------------
step "2/8 Node.js 준비 (프로그램 폴더 안에만 넣어요)"
mkdir -p "$AIO_DIR"
NODE_VER=$(curl -fsSL https://nodejs.org/dist/index.json | python3 -c "
import sys, json
for r in json.load(sys.stdin):
    if r.get('lts') and '$NARCH' in r.get('files', []):
        print(r['version']); break" || true)
[ -n "$NODE_VER" ] || NODE_VER=v22.12.0
if [ -x "$AIO_DIR/node/bin/node" ] && [ "$("$AIO_DIR/node/bin/node" -v)" = "$NODE_VER" ]; then
  echo "Node.js $NODE_VER 이미 있어요"
else
  TMP=$(mktemp -d)
  NAME="node-$NODE_VER-$NARCH"
  curl -fsSL "https://nodejs.org/dist/$NODE_VER/$NAME.tar.xz" -o "$TMP/$NAME.tar.xz"
  curl -fsSL "https://nodejs.org/dist/$NODE_VER/SHASUMS256.txt" -o "$TMP/SHASUMS256.txt"
  (cd "$TMP" && grep " $NAME.tar.xz\$" SHASUMS256.txt | sha256sum -c -) || fail "내려받은 Node.js 파일이 원본과 달라요."
  tar -xJf "$TMP/$NAME.tar.xz" -C "$TMP"
  rm -rf "$AIO_DIR/node" && mv "$TMP/$NAME" "$AIO_DIR/node"
  rm -rf "$TMP"
  echo "Node.js $NODE_VER 준비 완료"
fi

# ---------------------------------------------------------------
step "3/8 AI 사무실 프로그램 넣기"
id -u "$AIO_USER" >/dev/null 2>&1 || useradd --system --home "$AIO_DIR" --shell /usr/sbin/nologin "$AIO_USER"
TMP=$(mktemp -d)
base64 -d > "$TMP/app.tgz" <<'AIO_PAYLOAD'
