s/PZ+ex8dj47n53Pzmfns/PZ+ex8/v/5/D9aj93bAAAFAA==
AIO_PAYLOAD
rm -rf "$AIO_DIR/app.new" && mkdir -p "$AIO_DIR/app.new"
tar -xzf "$TMP/app.tgz" -C "$AIO_DIR/app.new"
rm -rf "$AIO_DIR/app.old"; [ -d "$AIO_DIR/app" ] && mv "$AIO_DIR/app" "$AIO_DIR/app.old"
mv "$AIO_DIR/app.new/app" "$AIO_DIR/app" && rm -rf "$AIO_DIR/app.new" "$AIO_DIR/app.old" "$TMP"
mkdir -p "$AIO_DIR/받은편지함" "$AIO_DIR/프로젝트" "$AIO_DIR/결과"
chown -R "$AIO_USER:$AIO_USER" "$AIO_DIR"
chmod 750 "$AIO_DIR"
"$AIO_DIR/node/bin/node" --check "$AIO_DIR/app/server.js" || fail "프로그램 파일이 깨졌어요."
echo "프로그램 버전 $AIO_VERSION"

# ---------------------------------------------------------------
step "4/8 로그인 비밀번호"
SETTINGS="$AIO_DIR/설정.json"
PW_NOTE=""
if [ -n "${AIO_PASSWORD:-}" ]; then
  [ "${#AIO_PASSWORD}" -ge 8 ] || fail "AIO_PASSWORD는 8글자 이상이어야 해요."
  runuser -u "$AIO_USER" -- env AIO_PASSWORD="$AIO_PASSWORD" "$AIO_DIR/node/bin/node" "$AIO_DIR/app/auth.js" set-password --initial
  PW_NOTE="설치할 때 정한 비밀번호 (로그인 후 꼭 바꿔 주세요)"
elif [ -f "$SETTINGS" ] && grep -q '"auth"' "$SETTINGS"; then
  PW_NOTE="예전에 쓰던 비밀번호 그대로"
else
  GEN=$(python3 -c "import secrets,string;a=string.ascii_letters+string.digits;print(''.join(secrets.choice(a) for _ in range(14)))")
  runuser -u "$AIO_USER" -- env AIO_PASSWORD="$GEN" "$AIO_DIR/node/bin/node" "$AIO_DIR/app/auth.js" set-password --initial
  umask 077; echo "$GEN" > /root/ai-office-password.txt
  PW_NOTE="$GEN   (서버의 /root/ai-office-password.txt 에도 적어 뒀어요)"
fi
chown "$AIO_USER:$AIO_USER" "$SETTINGS"; chmod 600 "$SETTINGS"

# ---------------------------------------------------------------
step "5/8 무료 AI (Ollama)"
if [ "${AIO_NO_OLLAMA:-0}" = 1 ]; then
  echo "건너뛰어요 (AI 키만 써요)"
else
  if ! command -v ollama >/dev/null 2>&1; then
    curl -fsSL https://ollama.com/install.sh | sh || echo "!! Ollama 설치 실패 — AI 키로는 그대로 쓸 수 있어요"
  else
    echo "Ollama 이미 있어요"
  fi
  MODEL="${AIO_MODEL:-qwen2.5-coder:3b}"
  if command -v ollama >/dev/null 2>&1 && [ "$MODEL" != none ]; then
    # 설정에 모델을 적어 두고, 내려받기는 뒤에서 천천히 해요 (설치는 바로 끝나요)
    runuser -u "$AIO_USER" -- "$AIO_DIR/node/bin/node" -e "
      const fs=require('fs'),f='$SETTINGS';let s={};try{s=JSON.parse(fs.readFileSync(f,'utf8'))}catch{}
      if(!s.model){s.model='$MODEL';fs.writeFileSync(f,JSON.stringify(s,null,2))}"
    systemctl enable --now ollama >/dev/null 2>&1 || true
    systemd-run --unit="ai-office-pull-$(date +%s)" --collect "$(command -v ollama)" pull "$MODEL" >/dev/null 2>&1 \
      && echo "무료 AI '$MODEL' 내려받기를 시작했어요 (몇 분 걸려요, 화면에서 진행을 볼 수 있어요)" || true
  fi
fi

# ---------------------------------------------------------------
step "6/8 https 문지기 (Caddy)"
PUBLIC_IP=$(curl -fsS4 --max-time 10 https://api.ipify.org || curl -fsS4 --max-time 10 https://ifconfig.me || true)
if [ -n "${AIO_DOMAIN:-}" ]; then HOSTNAME_PUB="$AIO_DOMAIN"
elif [ -n "$PUBLIC_IP" ]; then HOSTNAME_PUB="${PUBLIC_IP//./-}.sslip.io"
else fail "서버의 공개 IP를 알아내지 못했어요. AIO_DOMAIN 을 정해 주세요."; fi
HOSTNAME_PUB=$(echo "$HOSTNAME_PUB" | tr 'A-Z' 'a-z')
if ! command -v caddy >/dev/null 2>&1; then
  curl -1sLf 'https://dl.cloudsmith.io/public/caddy/stable/gpg.key' | gpg --dearmor --yes -o /usr/share/keyrings/caddy-stable-archive-keyring.gpg
  curl -1sLf 'https://dl.cloudsmith.io/public/caddy/stable/debian.deb.txt' > /etc/apt/sources.list.d/caddy-stable.list
  apt-get update -y && apt-get install -y caddy
fi
cat > /etc/caddy/Caddyfile <<CADDY
# AI 사무실 (install.sh 가 만든 파일)
$HOSTNAME_PUB {
	encode gzip
	header {
		Strict-Transport-Security "max-age=31536000"
		-Server
	}
	reverse_proxy 127.0.0.1:8787
}
CADDY
caddy validate --config /etc/caddy/Caddyfile --adapter caddyfile >/dev/null || fail "https 설정 파일이 잘못됐어요."
systemctl enable caddy >/dev/null 2>&1 || true
systemctl reload caddy 2>/dev/null || systemctl restart caddy

# ---------------------------------------------------------------
step "7/8 방화벽 (서버 안쪽 80·443 열기)"
for PORT in 80 443; do
  if ! iptables -C INPUT -p tcp -m state --state NEW --dport "$PORT" -j ACCEPT 2>/dev/null; then
    N=$(iptables -L INPUT --line-numbers -n | awk '/REJECT|DROP/ {print $1; exit}')
    if [ -n "$N" ]; then iptables -I INPUT "$N" -p tcp -m state --state NEW --dport "$PORT" -j ACCEPT
    else iptables -A INPUT -p tcp -m state --state NEW --dport "$PORT" -j ACCEPT; fi
  fi
done
netfilter-persistent save >/dev/null 2>&1 || true
if command -v ufw >/dev/null 2>&1 && ufw status | grep -q active; then ufw allow 80/tcp; ufw allow 443/tcp; fi
echo "서버 안쪽 방화벽 열기 완료 (Oracle 웹 화면의 '보안 목록'도 열어야 해요)"

# ---------------------------------------------------------------
step "8/8 자동 실행 (서버가 다시 켜져도 알아서 시작)"
cat > /etc/systemd/system/ai-office.service <<UNIT
[Unit]
Description=AI 사무실
After=network-online.target
Wants=network-online.target

[Service]
User=$AIO_USER
WorkingDirectory=$AIO_DIR
Environment=AIO_SERVER=1
Environment=AIO_PUBLIC_HOST=$HOSTNAME_PUB
ExecStart=$AIO_DIR/node/bin/node $AIO_DIR/app/server.js --no-open
Restart=always
RestartSec=5
NoNewPrivileges=yes
ProtectSystem=strict
ProtectHome=yes
PrivateTmp=yes
ReadWritePaths=$AIO_DIR

[Install]
WantedBy=multi-user.target
UNIT
systemctl daemon-reload
systemctl enable ai-office >/dev/null 2>&1
systemctl restart ai-office

# ---------------------------------------------------------------
step "확인"
OK=0
for i in $(seq 1 30); do
  CODE=$(curl -s -o /dev/null -w '%{http_code}' -H "Host: $HOSTNAME_PUB" http://127.0.0.1:8787/login || true)
  [ "$CODE" = 200 ] && { OK=1; break; }
  sleep 1
done
[ "$OK" = 1 ] || { journalctl -u ai-office -n 30 --no-pager || true; fail "AI 사무실이 켜지지 않았어요."; }
echo "✅ AI 사무실이 서버 안에서 켜졌어요"
HTTPS_OK=0
for i in $(seq 1 20); do
  if curl -fsS -o /dev/null --max-time 10 "https://$HOSTNAME_PUB/login" 2>/dev/null; then HTTPS_OK=1; break; fi
  sleep 3
done
[ "$HTTPS_OK" = 1 ] && echo "✅ https 주소도 열려요" || echo "⏳ https 주소는 아직이에요. Oracle '보안 목록'에서 80·443을 열었는지 확인해 주세요 (열면 1~2분 뒤 열려요)."

cat > "$AIO_DIR/설치결과.txt" <<DONE
AI 사무실 서버 설치 결과 ($(date))
주소: https://$HOSTNAME_PUB
비밀번호: $PW_NOTE
프로그램 버전: $AIO_VERSION
DONE
chown "$AIO_USER:$AIO_USER" "$AIO_DIR/설치결과.txt"; chmod 600 "$AIO_DIR/설치결과.txt"

echo
echo "=============================================================="
echo "  🎉 설치 끝!"
echo "  주소:     https://$HOSTNAME_PUB"
echo "  비밀번호: $PW_NOTE"
echo "  (휴대폰이나 아무 컴퓨터 브라우저에서 위 주소로 들어가세요)"
echo "=============================================================="
}

main "$@" </dev/null
